/// <summary>
/// Phase 1 of the SO extraction pipeline: dialog, credit check, ItemId-bundled guide check
/// and reservation, then hands off to METSalesPickingListFulfillmentBatch (Phase 2).
/// </summary>
class METSalesPickingListReservationBatch extends METRunBaseBatchMultiThreadBase
{
    container                   salesOrderList;
    container                   csdSalesOrderList;
    str                         csdGuid;
    boolean                     continueFromStagingLane;
    InventLocationId            extractionInventLocationId;
    METSalesOrderExtractionId   extractionId;
    container                   processedSalesContainer;
    container                   shipmentIdList;
    utcdatetime                 csdOrderExtractDateTime;
    container                   lineTaskBundles;
    boolean                     useLineLevelThreading;

    DialogField                 dlgOrderCount;
    DialogField                 dlgExtractionId;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        salesOrderList,
        csdSalesOrderList,
        csdGuid,
        continueFromStagingLane,
        extractionInventLocationId,
        extractionId,
        processedSalesContainer,
        shipmentIdList,
        csdOrderExtractDateTime,
        lineTaskBundles,
        useLineLevelThreading
    #endmacro

}

Method.Source:
/// <summary>
/// Builds a new instance from the selected SOs and the CSD/staging-lane context gathered in main().
/// </summary>
/// <param name = "_salesOrderList">Selected SalesIds</param>
/// <param name = "_csdSalesOrderList">CSD SalesIds among the selection</param>
/// <param name = "_csdGuid">CSD wave GUID</param>
/// <param name = "_continueFromStagingLane">Staging-lane continuation flag</param>
/// <param name = "_extractionInventLocationId">Inventory location for the extraction header</param>
/// <param name = "_useLineLevelThreading">True for the new V2 flow, false for legacy V1</param>
/// <returns>The constructed instance</returns>
public static METSalesPickingListReservationBatch construct(
    container            _salesOrderList,
    container            _csdSalesOrderList,
    str                  _csdGuid,
    boolean              _continueFromStagingLane,
    InventLocationId     _extractionInventLocationId,
    boolean              _useLineLevelThreading)
{
    METSalesPickingListReservationBatch batch = new METSalesPickingListReservationBatch();

    batch.salesOrderList             = _salesOrderList;
    batch.csdSalesOrderList          = _csdSalesOrderList;
    batch.csdGuid                    = _csdGuid;
    batch.continueFromStagingLane    = _continueFromStagingLane;
    batch.extractionInventLocationId = _extractionInventLocationId;
    batch.useLineLevelThreading      = _useLineLevelThreading;

    return batch;
}

/// <summary>
/// Shows order count and the pre-allocated ExtractionId (non-editable); never shown for
/// V1 - see showDialog().
/// </summary>
/// <returns>The dialog instance</returns>
public Object dialog()
{
    DialogRunbase dialog = super();

    if (!extractionId)
    {
        METSalesOrderExtractionTable extractionHeaderPreview;
        extractionHeaderPreview.initValue();
        extractionId = extractionHeaderPreview.ExtractionId;
    }

    dlgOrderCount   = dialog.addFieldValue(extendedtypestr(Integer), conLen(salesOrderList), "@MET:METSelectedOrderCount");
    dlgExtractionId = dialog.addFieldValue(extendedtypestr(METSalesOrderExtractionId), extractionId, "@MET:METExtractionIdLabel");

    dlgOrderCount.allowEdit(false);
    dlgExtractionId.allowEdit(false);

    return dialog;
}

/// <summary>
/// Packs batchIdentifier (base class) plus this class's own fields for batch/runtime-task serialization.
/// </summary>
/// <returns>Packed state</returns>
public container pack()
{
    return [#CurrentVersion, #CurrentList, super()];
}

/// <summary>
/// Reverses pack().
/// </summary>
/// <param name = "_packedClass">Packed state produced by pack()</param>
/// <returns>True if the packed version was recognized</returns>
public boolean unpack(container _packedClass)
{
    Version   version = RunBase::getVersion(_packedClass);
    container baseCon;

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, baseCon] = _packedClass;
            super(baseCon);
            break;
        default:
            return false;
    }
    return true;
}

/// <summary>
/// V1 always runs in batch; V2 lets the dialog's own batch checkbox decide.
/// </summary>
/// <returns>True to force batch execution</returns>
public boolean mustGoBatch()
{
    return !useLineLevelThreading;
}

/// <summary>
/// Lets runOperation() execute in a new session (needed for the non-batch/synchronous path).
/// </summary>
/// <returns>Always true</returns>
public boolean canRunInNewSession()
{
    return true;
}

/// <summary>
/// Static fallback caption; actual per-task captions come from caption() instead.
/// </summary>
/// <returns>The fallback caption</returns>
public static ClassDescription description()
{
    return "@MET:MetPickingListGeneration";
}

/// <summary>
/// Orchestrates the parent-task setup: flag orders, delegate to V1, or run V2's setup steps.
/// </summary>
protected void runStartTask()
{
    this.flagOrdersAsProcessing();

    if (!useLineLevelThreading)
    {
        this.runLegacyFlow();
        return;
    }

    this.insertExtractionHeaderAndLines();
    this.filterEligibleAndStampActions();

    if (conLen(processedSalesContainer) == 0)
    {
        return;
    }

    METCustParameters metCustParameters = METCustParameters::Find();
    int               taskCount = metCustParameters.SalesExtractionBatchLineTaskCount > 0 ? metCustParameters.SalesExtractionBatchLineTaskCount : 1;

    lineTaskBundles = this.buildLineTaskBundles(processedSalesContainer, taskCount);
}

/// <summary>
/// Returns one identifier per non-empty reservation bundle.
/// </summary>
/// <returns>Container of bundle-index identifiers</returns>
protected container getBatchIdentifiersRangeCon()
{
    container res;
    int       i;

    for (i = 1; i <= conLen(lineTaskBundles); i++)
    {
        if (conLen(conPeek(lineTaskBundles, i)) > 0)
        {
            res += int2str(i);
        }
    }

    return res;
}

/// <summary>
/// Resolves the entity type and delegates to the matching decision matrix.
/// </summary>
/// <param name = "_salesId">Sales order to decide the action for</param>
/// <returns>The decided action code</returns>
private str decideActionToPerform(SalesId _salesId)
{
    SalesTable        salesTable      = SalesTable::find(_salesId);
    METSalesTable     metSalesTable   = METSalesTable::findByRefRecId(salesTable.RecId);
    InventParameters  inventParameter = InventParameters::find();
    InventLocation    inventLocation  = InventLocation::find(salesTable.InventLocationId);

    if (inventParameter.METSupplyFromTransfer == NoYes::Yes)
    {
        return this.decideActionToPerformFood(salesTable, metSalesTable, inventLocation);
    }

    return this.decideActionToPerformLiquor(salesTable, metSalesTable, inventLocation);
}

/// <summary>
/// Persists the decided action onto the extraction line.
/// </summary>
/// <param name = "_extractionId">Owning ExtractionId</param>
/// <param name = "_salesId">Sales order the line belongs to</param>
/// <param name = "_actionToPerform">Decided action code</param>
private void stampActionToPerformOnExtractionLine(METSalesOrderExtractionId _extractionId, SalesId _salesId, str _actionToPerform)
{
    METSalesOrderExtractionLine extractionLine = METSalesOrderExtractionLine::find(_extractionId, _salesId, true);

    if (extractionLine.RecId)
    {
        extractionLine.ActionToPerform = _actionToPerform;
        extractionLine.update();
    }
}

/// <summary>
/// Stamps the CSD extract datetime on the SO, retrying on deadlock/update conflict.
/// </summary>
/// <param name = "_csdSalesOrderList">CSD SalesIds for this extraction</param>
/// <param name = "_salesId">Sales order to stamp, if it is a CSD order</param>
/// <param name = "_extractedDateTime">Datetime to stamp</param>
private void stampCsdExtractDateTime(container _csdSalesOrderList, SalesId _salesId, utcdatetime _extractedDateTime)
{
    #OCCRetryCount

    try
    {
        if (conFind(_csdSalesOrderList, _salesId) > 0)
        {
            SalesTable salesTable = SalesTable::find(_salesId, true);

            if (salesTable)
            {
                salesTable.skipDataMethods(true);
                salesTable.skipBusinessEvents(true);
                salesTable.METOrderExtractDateTime = _extractedDateTime;
                salesTable.update();
            }
        }
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        throw error("@SYS93835");
    }
}

/// <summary>
/// Per-bundle guide check + reservation for this task's assigned lines.
/// </summary>
protected void runThreadTask()
{
    #OCCRetryCount
    container  lineRecIdContainer = conPeek(lineTaskBundles, str2int(batchIdentifier));
    int        i;

    for (i = 1; i <= conLen(lineRecIdContainer); i++)
    {
        RefRecId lineRecId = conPeek(lineRecIdContainer, i);

        try
        {
            SalesLine salesLineLocal = SalesLine::findRecId(lineRecId, true);

            if (salesLineLocal.RecId)
            {
                str lineActionToPerform = this.readStoredActionToPerform(extractionId, salesLineLocal.SalesId);

                this.performGuideCheckForLine(salesLineLocal);

                if (lineActionToPerform == METConstants::SOExtractReservedSOPickAndTO
                 || lineActionToPerform == METConstants::SOExtractReservedSOPickOnly)
                {
                    SalesTable reservationSalesTable = salesLineLocal.salesTable();
                    METStockReservation::construct(reservationSalesTable).processV2ForLines([lineRecId], extractionId);
                }
            }
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }
}

/// <summary>
/// Reads back the ActionToPerform stamped during runStartTask().
/// </summary>
/// <param name = "_extractionId">Owning ExtractionId</param>
/// <param name = "_salesId">Sales order to look up</param>
/// <returns>The stored action code</returns>
private str readStoredActionToPerform(METSalesOrderExtractionId _extractionId, SalesId _salesId)
{
    METSalesOrderExtractionLine extractionLine = METSalesOrderExtractionLine::find(_extractionId, _salesId);

    return extractionLine.ActionToPerform;
}

/// <summary>
/// Builds a SalesUpdateRemain configured for extraction, with business events skipped.
/// </summary>
/// <returns>The configured SalesUpdateRemain instance</returns>
private SalesUpdateRemain buildSalesUpdateRemain()
{
    SalesUpdateRemain salesUpdateRemainLocal = SalesUpdateRemain::construct();
    salesUpdateRemainLocal.metParmIsExtraction(true);
    salesUpdateRemainLocal.parmSkipBusinessEvents(true);

    return salesUpdateRemainLocal;
}

/// <summary>
/// Sell-to / do-not-sell-to guide check for one line: 8-tier priority (Customer, then
/// CustOpsGroup, then Site, then State - OnlySellTo checked before DoNotSellTo at each tier).
/// </summary>
/// <param name = "_salesLine">The line to check</param>
public void performGuideCheckForLine(SalesLine _salesLine)
{
    SalesLine               salesLine;
    METSalesLine            metSalesLine;
    METInventItemOrderSetup metInventItemOrderSetup;
    InventDim               inventDim;
    CustTable               custTable;
    LogisticsPostalAddress  deliveryAddress;
    METSalesOrderGuideItem  salesOrderGuideItemCustomerOnlySellTo, salesOrderGuideItemCustomerOperationsGroupOnlySellTo, salesOrderGuideItemSiteOnlySellTo, salesOrderGuideItemStateOnlySellTo, salesOrderGuideItemCustomerDoNotSellTo, salesOrderGuideItemCustomerOperationsGroupDoNotSellTo, salesOrderGuideItemSiteDoNotSellTo, salesOrderGuideItemStateDoNotSellTo;

    SalesTable salesTableLocal;

    salesTableLocal = SalesTable::find(_salesLine.SalesId, true);

    if (salesTableLocal.METOrderExtractStatus != METOrderExtractStatus::Open && salesTableLocal.METOrderExtractStatus != METOrderExtractStatus::ReadyForExtract)
    {
        return;
    }

    select firstonly METCustOperGroupId
        from custTable
        where custTable.AccountNum == salesTableLocal.CustAccount;

    while select salesLine
            where salesLine.RecId == _salesLine.RecId
            &&  salesLine.SalesStatus == SalesStatus::Backorder
            &&  salesLine.SalesId == salesTableLocal.SalesId
        join InventSiteId from inventDim
            where inventDim.InventDimId == salesLine.InventDimId
        join metSalesLine
            where metSalesLine.SalesLine == salesLine.RecId
        outer join ItemStatus, RecId from metInventItemOrderSetup
            where metInventItemOrderSetup.ItemId == salesLine.ItemId
            && METInventItemOrderSetup.SiteId == inventDim.InventSiteId
        outer join State from deliveryAddress
            where deliveryAddress.Location == salesLine.DeliveryPostalAddress
        outer join RecId from salesOrderGuideItemCustomerOnlySellTo
            where salesOrderGuideItemCustomerOnlySellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemCustomerOnlySellTo.ReferenceType == METSalesOrderGuideReferenceType::Customer
            && salesOrderGuideItemCustomerOnlySellTo.Type == METSalesOrderGuideType::OnlySellTo
            && salesOrderGuideItemCustomerOnlySellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemCustomerOnlySellTo.Reference != ''
        outer join RecId from salesOrderGuideItemCustomerOperationsGroupOnlySellTo
            where salesOrderGuideItemCustomerOperationsGroupOnlySellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.ReferenceType == METSalesOrderGuideReferenceType::CustomerOperationsGroup
            && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.Type == METSalesOrderGuideType::OnlySellTo
            && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.Reference != ''
        outer join RecId from salesOrderGuideItemSiteOnlySellTo
            where salesOrderGuideItemSiteOnlySellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemSiteOnlySellTo.ReferenceType == METSalesOrderGuideReferenceType::Site
            && salesOrderGuideItemSiteOnlySellTo.Type == METSalesOrderGuideType::OnlySellTo
            && salesOrderGuideItemSiteOnlySellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemSiteOnlySellTo.Reference != ''
        outer join RecId from salesOrderGuideItemStateOnlySellTo
            where salesOrderGuideItemStateOnlySellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemStateOnlySellTo.ReferenceType == METSalesOrderGuideReferenceType::State
            && salesOrderGuideItemStateOnlySellTo.Type == METSalesOrderGuideType::OnlySellTo
            && salesOrderGuideItemStateOnlySellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemStateOnlySellTo.Reference != ''
        outer join RecId from salesOrderGuideItemCustomerDoNotSellTo
            where salesOrderGuideItemCustomerDoNotSellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemCustomerDoNotSellTo.ReferenceType == METSalesOrderGuideReferenceType::Customer
            && salesOrderGuideItemCustomerDoNotSellTo.Reference == salesLine.CustAccount
            && salesOrderGuideItemCustomerDoNotSellTo.Type == METSalesOrderGuideType::DoNotSellTo
            && salesOrderGuideItemCustomerDoNotSellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemCustomerDoNotSellTo.Reference != ''
        outer join RecId from salesOrderGuideItemCustomerOperationsGroupDoNotSellTo
            where salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.ReferenceType == METSalesOrderGuideReferenceType::CustomerOperationsGroup
            && salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.Reference == custTable.METCustOperGroupId
            && salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.Type == METSalesOrderGuideType::DoNotSellTo
            && salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.Reference != ''
        outer join RecId from salesOrderGuideItemSiteDoNotSellTo
            where salesOrderGuideItemSiteDoNotSellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemSiteDoNotSellTo.ReferenceType == METSalesOrderGuideReferenceType::Site
            && salesOrderGuideItemSiteDoNotSellTo.Reference == inventDim.InventSiteId
            && salesOrderGuideItemSiteDoNotSellTo.Type == METSalesOrderGuideType::DoNotSellTo
            && salesOrderGuideItemSiteDoNotSellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemSiteDoNotSellTo.Reference != ''
        outer join RecId from salesOrderGuideItemStateDoNotSellTo
            where salesOrderGuideItemStateDoNotSellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemStateDoNotSellTo.ReferenceType == METSalesOrderGuideReferenceType::State
            && salesOrderGuideItemStateDoNotSellTo.Reference == deliveryAddress.State
            && salesOrderGuideItemStateDoNotSellTo.Type == METSalesOrderGuideType::DoNotSellTo
            && salesOrderGuideItemStateDoNotSellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemStateDoNotSellTo.Reference != ''
    {
        if (metInventItemOrderSetup.RecId
            && metInventItemOrderSetup.ItemStatus != METConstants::Active
            && metSalesLine.ReasonId != METConstants::NewReasonCode
            && metSalesLine.ReasonId != METConstants::DEL)
        {
            ttsbegin;
            metSalesLine.selectForUpdate(true);
            metSalesLine.ReasonId = METConstants::NewReasonCode;
            metSalesLine.skipBusinessEvents(true);
            metSalesLine.update();
            ttscommit;

            continue;
        }

        if (salesOrderGuideItemCustomerOnlySellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != '')
            {
                ttsbegin;
                metSalesLine.selectForUpdate(true);

                if (salesOrderGuideItemCustomerOnlySellTo.RecId && salesOrderGuideItemCustomerOnlySellTo.Reference == salesLine.CustAccount)
                {
                    metSalesLine.ReasonId = '';
                }
                else
                {
                    metSalesLine.ReasonId = METConstants::NIRReasonCode;
                    metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                }
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (salesOrderGuideItemCustomerOnlySellTo.RecId && salesOrderGuideItemCustomerOnlySellTo.Reference != salesLine.CustAccount)
                {
                    salesLine.selectForUpdate(true);
                    if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                    {
                        this.buildSalesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                    }
                    else
                    {
                        this.buildSalesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                    }
                }

                ttscommit;
            }

            continue;
        }

        if (salesOrderGuideItemCustomerDoNotSellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != METConstants::NIRReasonCode)
            {
                ttsbegin;
                salesLine.selectForUpdate(true);
                metSalesLine.selectForUpdate(true);
                metSalesLine.ReasonId = METConstants::NIRReasonCode;
                metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                {
                    this.buildSalesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                }
                else
                {
                    this.buildSalesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                }

                ttscommit;
            }

            continue;
        }

        if (salesOrderGuideItemCustomerOperationsGroupOnlySellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != '')
            {
                ttsbegin;
                metSalesLine.selectForUpdate(true);
                if (salesOrderGuideItemCustomerOperationsGroupOnlySellTo.RecId && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.Reference == custTable.METCustOperGroupId)
                {
                    metSalesLine.ReasonId = '';
                }
                else
                {
                    metSalesLine.ReasonId = METConstants::NIRReasonCode;
                    metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                }
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (salesOrderGuideItemCustomerOperationsGroupOnlySellTo.RecId && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.Reference != custTable.METCustOperGroupId)
                {
                    salesLine.selectForUpdate(true);
                    if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                    {
                        this.buildSalesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                    }
                    else
                    {
                        this.buildSalesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                    }
                }

                ttscommit;
            }

            continue;
        }

        if (salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != METConstants::NIRReasonCode)
            {
                ttsbegin;
                salesLine.selectForUpdate(true);
                metSalesLine.selectForUpdate(true);
                metSalesLine.ReasonId = METConstants::NIRReasonCode;
                metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                {
                    this.buildSalesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                }
                else
                {
                    this.buildSalesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                }

                ttscommit;
            }

            continue;
        }

        if (salesOrderGuideItemSiteOnlySellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != '')
            {
                ttsbegin;
                metSalesLine.selectForUpdate(true);

                if (salesOrderGuideItemSiteOnlySellTo.RecId && salesOrderGuideItemSiteOnlySellTo.Reference == inventDim.InventSiteId)
                {
                    metSalesLine.ReasonId = '';
                }
                else
                {
                    metSalesLine.ReasonId = METConstants::NIRReasonCode;
                    metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                }

                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (salesOrderGuideItemSiteOnlySellTo.RecId && salesOrderGuideItemSiteOnlySellTo.Reference != inventDim.InventSiteId)
                {
                    salesLine.selectForUpdate(true);
                    if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                    {
                        this.buildSalesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                    }
                    else
                    {
                        this.buildSalesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                    }
                }

                ttscommit;
            }

            continue;
        }

        if (salesOrderGuideItemSiteDoNotSellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != METConstants::NIRReasonCode)
            {
                ttsbegin;
                salesLine.selectForUpdate(true);

                metSalesLine.selectForUpdate(true);
                metSalesLine.ReasonId = METConstants::NIRReasonCode;
                metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                {
                    this.buildSalesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                }
                else
                {
                    this.buildSalesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                }

                ttscommit;
            }

            continue;
        }

        if (salesOrderGuideItemStateOnlySellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != '')
            {
                ttsbegin;
                metSalesLine.selectForUpdate(true);

                if (salesOrderGuideItemStateOnlySellTo.RecId && salesOrderGuideItemStateOnlySellTo.Reference == deliveryAddress.State)
                {
                    metSalesLine.ReasonId = '';
                }
                else
                {
                    metSalesLine.ReasonId = METConstants::NIRReasonCode;
                    metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                }

                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (salesOrderGuideItemStateOnlySellTo.RecId && salesOrderGuideItemStateOnlySellTo.Reference != deliveryAddress.State)
                {
                    salesLine.selectForUpdate(true);
                    if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                    {
                        this.buildSalesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                    }
                    else
                    {
                        this.buildSalesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                    }
                }

                ttscommit;
            }

            continue;
        }

        if (salesOrderGuideItemStateDoNotSellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != METConstants::NIRReasonCode)
            {
                ttsbegin;
                salesLine.selectForUpdate(true);
                metSalesLine.selectForUpdate(true);
                metSalesLine.ReasonId = METConstants::NIRReasonCode;
                metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                {
                    this.buildSalesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                }
                else
                {
                    this.buildSalesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                }

                ttscommit;
            }

            continue;
        }

        if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != '')
        {
            ttsbegin;
            metSalesLine.selectForUpdate(true);
            metSalesLine.ReasonId = '';
            metSalesLine.skipBusinessEvents(true);
            metSalesLine.update();
            ttscommit;
        }
    }
}

/// <summary>
/// Orchestrates the End task: spawn per-SO tasks, the End/export task, then the CSD task.
/// </summary>
protected void runFinalTask()
{
    boolean                              isBatchMode = this.isInBatch();
    Batch                                currentBatchTask;
    BatchHeader                          fulfillmentBatchHeader;
    RefRecId                             anchorRecId;
    List                                 fulfillmentTaskList;
    METSalesPickingListFulfillmentBatch  endTask;

    if (isBatchMode)
    {
        currentBatchTask       = this.parmCurrentBatch();
        fulfillmentBatchHeader = BatchHeader::construct(currentBatchTask.BatchJobId);
        anchorRecId            = currentBatchTask.RecId;
    }

    fulfillmentTaskList = this.spawnPerSOTasks(isBatchMode, currentBatchTask, fulfillmentBatchHeader, anchorRecId);

    if (fulfillmentTaskList.elements() == 0)
    {
        return;
    }

    endTask = this.spawnEndTask(isBatchMode, currentBatchTask, fulfillmentBatchHeader, anchorRecId, fulfillmentTaskList);

    this.spawnCsdTransferOrderTask(isBatchMode, fulfillmentBatchHeader, anchorRecId, fulfillmentTaskList, endTask);

    if (isBatchMode)
    {
        fulfillmentBatchHeader.save();
    }
}

/// <summary>
/// Extract-button entry point: scans the selected orders, resolves CSD/staging-lane
/// context, then prompts (V2) or silently schedules (V1) this batch.
/// </summary>
/// <param name = "_args">Caller args - the extraction screen's form is expected</param>
[SuppressBPWarning('BPErrorSelectUsingFirstOnly', 'This is required as a complete set of buffer needs to be passed')]
public static void main(Args _args)
{
    METSalesPickingListReservationBatch  reservationBatch;
    FormRun                              formRun;
    container                            salesOrderOSCCon, csdSalesOrderCon, csdsalesOrderCustAccountCon;
    SalesTable                           salesTableLoc;
    boolean                              isCSDWarehouse;
    METNumberOfCustomers                 numberOfCSDCustomers;
    InventLocationId                     csdWareHouse;
    InventLocationId                     extractionInventLocationId;
    InventLocation                       inventLocation;
    boolean                              boxCalled = false;
    boolean                              isCSDWareHouseChecked;
    boolean                              continueFromStagingLane;
    boolean                              useLineLevelThreading;

    formRun = _args.caller();

    FormDataSource              tmpFormDataSource = formRun.dataSource(formDataSourceStr(METOrderExtractScreen, METOrderExtractScreenTmpDS));
    METOrderExtractScreenTmp    metOrderExtractScreenTmp;

    metOrderExtractScreenTmp = tmpFormDataSource.getFirst(false);

    while select metOrderExtractScreenTmp
        where metOrderExtractScreenTmp.Selection == NoYes::Yes
        join salesTableLoc
            where salesTableLoc.SalesId == metOrderExtractScreenTmp.SalesId
    {
        if (!boxCalled && salesTableLoc.METOrderExtractStatus == METOrderExtractStatus::Open)
        {
            if (Box::yesNo("@MET:SOUpdateExtraction", DialogButton::No) == DialogButton::No)
            {
                break;
            }
            boxCalled = true;
        }

        if (salesTableLoc.METOrderExtractStatus != METOrderExtractStatus::Extracted)
        {
            if (!salesTableLoc.METRoute || !salesTableLoc.METRouteStopNum)
            {
                warning(strFmt("@MET:OrderExtractMissingRouteWarning", salesTableLoc.SalesId));
                continue;
            }
        }

        if (!isCSDWareHouseChecked && !isCSDWarehouse && salesTableLoc.RecId != 0)
        {
            select firstonly METNumberOfCustomers, RecId from inventLocation
                where inventLocation.InventLocationId == salesTableLoc.InventLocationId
                &&  inventLocation.METCSDWarehouse == NoYes::Yes;

            isCSDWareHouseChecked = true;

            if (inventLocation.RecId != 0)
            {
                numberOfCSDCustomers = inventLocation.METNumberOfCustomers;
                csdWareHouse = salesTableLoc.InventLocationId;
                isCSDWarehouse = true;
            }
        }

        if (isCSDWarehouse && salesTableLoc.RecId != 0)
        {
            if (!conFind(csdSalesOrderCon, salesTableLoc.SalesId))
            {
                csdSalesOrderCon += salesTableLoc.SalesId;
            }

            if (!conFind(csdsalesOrderCustAccountCon, salesTableLoc.CustAccount))
            {
                csdsalesOrderCustAccountCon += salesTableLoc.CustAccount;
            }
        }

        if (!conFind(salesOrderOSCCon, salesTableLoc.SalesId))
        {
            salesOrderOSCCon += salesTableLoc.SalesId;
        }

        if (!extractionInventLocationId && salesTableLoc.RecId)
        {
            extractionInventLocationId = salesTableLoc.InventLocationId;
        }
    }

    //CB123 SalesOrderExtractScreenforCSD -start
    if (conLen(csdsalesOrderCustAccountCon) > numberOfCSDCustomers)
    {
        throw error("@MET:CSDMaximumCustomersExceeded");
    }
    //CB123 SalesOrderExtractScreenforCSD -end

    if (conLen(salesOrderOSCCon))
    {
        METCustParameters metCustParameters = METCustParameters::find();
        useLineLevelThreading = metCustParameters.SalesExtractionDisableLineLevelThreading == NoYes::No;

        //CB123 SalesOrderExtractScreenforCSD -start
        if (conLen(csdSalesOrderCon))
        {
            // Introduce the Code to check for 'Continue  from staging lane - XXX ?'
            METNextCustStartingPosition custStartingPosition = InventLocation::find(salesTableLoc.InventLocationId).METCustStartingPosition;

            if (isCSDWarehouse && custStartingPosition > 0)
            {
                //Check for next staging lane position stored for the warehouse in METStagingLanePositionCounter table.
                METStagingLanePositionCounter metStagingLanePositionCounter = METStagingLanePositionCounter::find(salesTableLoc.InventLocationId, true);
                METNextCustStartingPosition nextStagingLane = metStagingLanePositionCounter.NextStagingLane;

                if (!nextStagingLane)
                {
                    nextStagingLane = custStartingPosition;
                }

                if (Box::yesNo(strFmt("@MET:ContinueFromStagingLane", nextStagingLane), DialogButton::No) == DialogButton::No)
                {
                    continueFromStagingLane = false;

                    if (metStagingLanePositionCounter.RecId)
                    {
                        ttsbegin;
                        metStagingLanePositionCounter.delete();
                        ttscommit;
                    }
                }
                else
                {
                    continueFromStagingLane = true;
                }
            }
        }

        reservationBatch = METSalesPickingListReservationBatch::construct(
            salesOrderOSCCon,
            csdSalesOrderCon,
            guid2Str(newGuid()),
            continueFromStagingLane,
            extractionInventLocationId,
            useLineLevelThreading);

        if (metCustParameters.SalesExtractionBatchGroupId)
        {
            reservationBatch.batchInfo().parmGroupId(metCustParameters.SalesExtractionBatchGroupId);
        }

        if (!useLineLevelThreading)
        {
            reservationBatch.batchInfo().parmBatchExecute(NoYes::Yes);
        }

        if (reservationBatch.prompt())
        {
            reservationBatch.runOperation();
        }
    }
    else
    {
        warning("@MET:NoSalesOrderToProcess");
    }
}

/// <summary>
/// V1 skips the base class's parent/thread/final dispatch entirely and just runs runStartTask() once.
/// </summary>
public void run()
{
    if (!useLineLevelThreading)
    {
        this.runStartTask();
        return;
    }

    super();
}

/// <summary>
/// No dialog at all for V1 - main() silently forces batch instead.
/// </summary>
/// <returns>True to show the dialog (V2 only)</returns>
public boolean showDialog()
{
    return useLineLevelThreading;
}

/// <summary>
/// Parameters are always set via code, never loaded from SysLastValue.
/// </summary>
/// <returns>Always false</returns>
public boolean allowSaveLast()
{
    return false;
}

/// <summary>
/// Per-role task caption: setup (named like the original job, by user, for ExtractionId),
/// bundle N, or dispatch-to-fulfillment.
/// </summary>
/// <returns>The caption for this task instance</returns>
public ClassDescription caption()
{
    if (batchIdentifier == this.finalTaskIdentifier())
    {
        return "@MET:METCaptionReservationDispatch";
    }
    else if (batchIdentifier)
    {
        return strFmt("@MET:METCaptionGuideCheckReservation", batchIdentifier);
    }
    else if (extractionId)
    {
        return strFmt("@MET:METCaptionReservationSetupForExtraction", "@MET:MetPickingListGeneration", curUserId(), extractionId);
    }

    return "@MET:MetPickingListGeneration";
}

/// <summary>
/// Sets METProcessing=Yes on each selected order that is still Open/ReadyForExtract.
/// </summary>
private void flagOrdersAsProcessing()
{
    int i;

    ttsbegin;

    for (i = 1; i <= conLen(salesOrderList); i++)
    {
        SalesId    currentSalesId = conPeek(salesOrderList, i);
        SalesTable salesTableToUpdate;
        salesTableToUpdate.skipBusinessEvents(true);
        select firstonly forupdate salesTableToUpdate where salesTableToUpdate.SalesId == currentSalesId;
        if (salesTableToUpdate.RecId && (salesTableToUpdate.METOrderExtractStatus == METOrderExtractStatus::Open || salesTableToUpdate.METOrderExtractStatus == METOrderExtractStatus::ReadyForExtract))
        {
            salesTableToUpdate.METProcessing = NoYes::Yes;
            salesTableToUpdate.doUpdate();
        }
    }

    ttscommit;
}

/// <summary>
/// V1: builds the original contract and hands off to METSalesPickingListGenerationService.
/// </summary>
private void runLegacyFlow()
{
    METSalesPickingListGenerationContract v1Contract = new METSalesPickingListGenerationContract();
    v1Contract.parmSalesOrderList(salesOrderList);
    v1Contract.parmCSDSalesOrderList(csdSalesOrderList);
    v1Contract.parmCsdGuid(csdGuid);
    v1Contract.parmContinueFromStagingLane(continueFromStagingLane);

    new METSalesPickingListGenerationService().process(v1Contract);
}

/// <summary>
/// Inserts the extraction header (reusing the dialog's pre-allocated ExtractionId) and one line per SO.
/// </summary>
private void insertExtractionHeaderAndLines()
{
    int                           i;
    METSalesOrderExtractionTable  extractionHeader;
    METSalesOrderExtractionLine   extractionLine;

    ttsbegin;

    if (extractionId)
    {
        extractionHeader.ExtractionId = extractionId;
    }
    extractionHeader.initValue();
    extractionHeader.InventLocationId = extractionInventLocationId;
    extractionHeader.ExtractionStatus = METSalesOrderExtractionStatus::Pending;
    extractionHeader.Exported         = NoYes::No;
    extractionHeader.insert();

    extractionId = extractionHeader.ExtractionId;

    for (i = 1; i <= conLen(salesOrderList); i++)
    {
        extractionLine.clear();
        extractionLine.ExtractionId     = extractionId;
        extractionLine.SalesId          = conPeek(salesOrderList, i);
        extractionLine.ExtractionStatus = METSalesOrderExtractionStatus::Pending;
        extractionLine.insert();
    }

    ttscommit;
}

/// <summary>
/// Credit-check filters the SO list, stamps shipment/CSD/action data, and builds processedSalesContainer.
/// </summary>
private void filterEligibleAndStampActions()
{
    int            i;
    SalesId        salesIdLocal;
    MetShipmentId  metShipmentId;
    utcdatetime    curDateTime = DateTimeUtil::getSystemDateTime();

    ttsbegin;

    for (i = 1; i <= conLen(salesOrderList); i++)
    {
        str actionToPerform;

        salesIdLocal = conPeek(salesOrderList, i);

        if (SalesTable::find(salesIdLocal).CredManInCreditControl)
        {
            warning(strFmt("@MET:SOCredMgmtValidation", salesIdLocal));
            continue;
        }

        METOrderShipmentLoadCreation shipmentLoadCreation = METOrderShipmentLoadCreation::construct(METOrderTransactionType::SalesOrder, salesIdLocal);
        metShipmentId = shipmentLoadCreation.createShippmentLoad(true, true);

        if (conFind(shipmentIdList, metShipmentId) == 0)
        {
            shipmentIdList += [metShipmentId];
        }

        this.stampCsdExtractDateTime(csdSalesOrderList, salesIdLocal, curDateTime);

        actionToPerform = this.decideActionToPerform(salesIdLocal);
        this.stampActionToPerformOnExtractionLine(extractionId, salesIdLocal, actionToPerform);

        processedSalesContainer += salesIdLocal;
    }

    if (conLen(processedSalesContainer) == 0)
    {
        ttsabort;
        return;
    }

    ttscommit;

    csdOrderExtractDateTime = curDateTime;
}

/// <summary>
/// Food-entity decision matrix - unchanged from the original Orchestrator.
/// </summary>
/// <param name = "_salesTable">The sales order</param>
/// <param name = "_metSalesTable">Metcash sales order extension</param>
/// <param name = "_inventLocation">The order's warehouse</param>
/// <returns>The decided action code</returns>
private str decideActionToPerformFood(SalesTable _salesTable, METSalesTable _metSalesTable, InventLocation _inventLocation)
{
    str actionToPerform;

    if (_metSalesTable.InternalCrossDockOrder == NoYes::Yes  &&
        _inventLocation.METCSDWarehouse == NoYes::No         &&
        _inventLocation.METPickDirector == NoYes::No         &&
        _inventLocation.METWaveRequired == NoYes::No)
    {
        actionToPerform = METConstants::SOExtractCreateOnlyTO;
    }
    else if (_metSalesTable.InternalCrossDockOrder == NoYes::No  &&
            _salesTable.METAllowBackOrders == NoYes::No          &&
            _inventLocation.METCSDWarehouse == NoYes::Yes        &&
            _inventLocation.METPickDirector == NoYes::No         &&
            _inventLocation.METWaveRequired == NoYes::Yes)
    {
        actionToPerform = METConstants::SOExtractOrderedSOPickOnly;
    }
    else if (_metSalesTable.InternalCrossDockOrder == NoYes::No  &&
            _salesTable.METAllowBackOrders == NoYes::No          &&
            _inventLocation.METCSDWarehouse == NoYes::Yes        &&
            _inventLocation.METPickDirector == NoYes::Yes        &&
            _inventLocation.METWaveRequired == NoYes::Yes)
    {
        actionToPerform = METConstants::SOExtractUpdateStatusOnly;
    }
    else if (_metSalesTable.InternalCrossDockOrder == NoYes::No  &&
            _salesTable.METAllowBackOrders == NoYes::No          &&
            _inventLocation.METCSDWarehouse == NoYes::Yes        &&
            _inventLocation.METPickDirector == NoYes::No         &&
            _inventLocation.METWaveRequired == NoYes::No)
    {
        actionToPerform = METConstants::SOExtractUpdateStatusOnly;
    }
    else if (_metSalesTable.InternalCrossDockOrder == NoYes::No  &&
            _salesTable.METAllowBackOrders == NoYes::No          &&
            _inventLocation.METCSDWarehouse == NoYes::No         &&
            _inventLocation.METPickDirector == NoYes::No         &&
            _inventLocation.METWaveRequired == NoYes::No)
    {
        actionToPerform = METConstants::SOExtractReservedSOPickOnly;
    }
    else if (_metSalesTable.InternalCrossDockOrder == NoYes::No  &&
            _salesTable.METAllowBackOrders == NoYes::Yes         &&
            _inventLocation.METCSDWarehouse == NoYes::No         &&
            _inventLocation.METPickDirector == NoYes::No         &&
            _inventLocation.METWaveRequired == NoYes::No)
    {
        actionToPerform = METConstants::SOExtractReservedSOPickOnly;
    }
    else if (_metSalesTable.InternalCrossDockOrder == NoYes::No  &&
            _salesTable.METAllowBackOrders == NoYes::Yes         &&
            _inventLocation.METCSDWarehouse == NoYes::Yes        &&
            _inventLocation.METPickDirector == NoYes::Yes        &&
            _inventLocation.METWaveRequired == NoYes::Yes)
    {
        actionToPerform = METConstants::SOExtractUpdateStatusOnly;
    }
    else if (_metSalesTable.InternalCrossDockOrder == NoYes::No  &&
            _salesTable.METAllowBackOrders == NoYes::Yes         &&
            _inventLocation.METCSDWarehouse == NoYes::Yes        &&
            _inventLocation.METPickDirector == NoYes::No         &&
            _inventLocation.METWaveRequired == NoYes::Yes)
    {
        actionToPerform = METConstants::SOExtractOrderedSOPickOnly;
    }
    else if (_metSalesTable.InternalCrossDockOrder == NoYes::No  &&
            _salesTable.METAllowBackOrders == NoYes::Yes         &&
            _inventLocation.METCSDWarehouse == NoYes::Yes        &&
            _inventLocation.METPickDirector == NoYes::No         &&
            _inventLocation.METWaveRequired == NoYes::No)
    {
        actionToPerform = METConstants::SOExtractUpdateStatusOnly;
    }
    else
    {
        actionToPerform = METConstants::SOExtractSkip;
    }

    return actionToPerform;
}

