/// <summary>
/// Groups every backorder-eligible line across all SOs by ItemId.
/// </summary>
/// <param name = "_salesIdContainer">SalesIds to scan</param>
/// <param name = "_itemLineMap">Map(ItemId -> container of line RecIds), filled in place</param>
/// <returns>Container of distinct ItemIds found</returns>
private container collectLinesByItem(container _salesIdContainer, Map _itemLineMap)
{
    SalesLine  salesLine;
    List       itemIdList = new List(Types::String);
    container  itemIdArr;
    int        i;

    for (i = 1; i <= conLen(_salesIdContainer); i++)
    {
        SalesId salesIdLocal = conPeek(_salesIdContainer, i);

        while select salesLine
            where salesLine.SalesId     == salesIdLocal
               && salesLine.SalesStatus != SalesStatus::Canceled
        {
            container existingLines = _itemLineMap.exists(salesLine.ItemId) ? _itemLineMap.lookup(salesLine.ItemId) : conNull();

            if (!_itemLineMap.exists(salesLine.ItemId))
            {
                itemIdList.addEnd(salesLine.ItemId);
            }

            _itemLineMap.insert(salesLine.ItemId, existingLines + salesLine.RecId);
        }
    }

    ListEnumerator itemEnum = itemIdList.getEnumerator();
    while (itemEnum.moveNext())
    {
        itemIdArr += itemEnum.current();
    }

    return itemIdArr;
}

/// <summary>
/// Selection sort so the heaviest items (most lines) get bundled first.
/// </summary>
/// <param name = "_itemIdArr">ItemIds to sort</param>
/// <param name = "_itemLineMap">Map(ItemId -> lines), used for the comparison</param>
/// <returns>ItemIds sorted by line count, descending</returns>
private container sortItemsByLineCountDescending(container _itemIdArr, Map _itemLineMap)
{
    int i, compareIdx;

    for (i = 1; i < conLen(_itemIdArr); i++)
    {
        int maxIdx = i;

        for (compareIdx = i + 1; compareIdx <= conLen(_itemIdArr); compareIdx++)
        {
            if (conLen(_itemLineMap.lookup(conPeek(_itemIdArr, compareIdx))) > conLen(_itemLineMap.lookup(conPeek(_itemIdArr, maxIdx))))
            {
                maxIdx = compareIdx;
            }
        }

        if (maxIdx != i)
        {
            str tmp    = conPeek(_itemIdArr, i);
            _itemIdArr = conPoke(_itemIdArr, i, conPeek(_itemIdArr, maxIdx));
            _itemIdArr = conPoke(_itemIdArr, maxIdx, tmp);
        }
    }

    return _itemIdArr;
}

/// <summary>
/// Creates one Class 2 pick-list task per eligible SO, either as a real batch task or run inline.
/// </summary>
/// <param name = "_isBatchMode">True if running as a real batch job</param>
/// <param name = "_currentBatchTask">The currently-executing batch task (batch mode only)</param>
/// <param name = "_fulfillmentBatchHeader">Batch header to add tasks to (batch mode only)</param>
/// <param name = "_anchorRecId">RecId to anchor runtime tasks to (batch mode only)</param>
/// <returns>The list of spawned/run Class 2 instances</returns>
private List spawnPerSOTasks(boolean _isBatchMode, Batch _currentBatchTask, BatchHeader _fulfillmentBatchHeader, RefRecId _anchorRecId)
{
    int  i;
    List fulfillmentTaskList = new List(Types::Class);

    for (i = 1; i <= conLen(processedSalesContainer); i++)
    {
        SalesId                               salesIdLocal = conPeek(processedSalesContainer, i);
        METSalesPickingListFulfillmentBatch   soTask = new METSalesPickingListFulfillmentBatch();
        int                                    csdPosition = conFind(csdSalesOrderList, salesIdLocal);

        soTask.parmSalesId(salesIdLocal);
        soTask.parmSalesOrderExtractionId(extractionId);
        soTask.parmContinueFromStagingLane(continueFromStagingLane);
        soTask.parmCSDSalesOrderCount(conLen(csdSalesOrderList));
        soTask.parmCSDSalesOrderExtractDateTime(csdOrderExtractDateTime);

        if (csdPosition > 0)
        {
            soTask.parmCSDSalesId(salesIdLocal);
        }

        if (csdGuid && conLen(csdSalesOrderList) > 0)
        {
            soTask.parmCsdGuid(csdGuid);
        }

        soTask.parmBatchIdentifier(salesIdLocal);

        if (_isBatchMode)
        {
            soTask.batchInfo().resetBatchHeader();
            soTask.batchInfo().parmGroupId(_currentBatchTask.GroupId);
            soTask.batchInfo().parmConstraintType(BatchConstraintType::And);
            soTask.batchInfo().parmDataareaId(_currentBatchTask.Company);
            _fulfillmentBatchHeader.addRuntimeTask(soTask, _anchorRecId);
        }
        else
        {
            soTask.run();
        }

        fulfillmentTaskList.addEnd(soTask);
    }

    return fulfillmentTaskList;
}

/// <summary>
/// Creates the Class 2 End/export task, dependent on every per-SO task in batch mode.
/// </summary>
/// <param name = "_isBatchMode">True if running as a real batch job</param>
/// <param name = "_currentBatchTask">The currently-executing batch task (batch mode only)</param>
/// <param name = "_fulfillmentBatchHeader">Batch header to add the task to (batch mode only)</param>
/// <param name = "_anchorRecId">RecId to anchor the runtime task to (batch mode only)</param>
/// <param name = "_fulfillmentTaskList">Per-SO tasks the End task depends on</param>
/// <returns>The spawned/run End task instance</returns>
private METSalesPickingListFulfillmentBatch spawnEndTask(boolean _isBatchMode, Batch _currentBatchTask, BatchHeader _fulfillmentBatchHeader, RefRecId _anchorRecId, List _fulfillmentTaskList)
{
    METSalesPickingListFulfillmentBatch endTask = new METSalesPickingListFulfillmentBatch();

    endTask.parmSalesOrderExtractionId(extractionId);
    endTask.parmShipmentIdList(shipmentIdList);
    endTask.parmCsdGuid(csdGuid);
    endTask.parmCSDSalesOrderList(csdSalesOrderList);
    endTask.parmCSDSalesOrderExtractDateTime(csdOrderExtractDateTime);

    if (conLen(csdSalesOrderList) > 0)
    {
        endTask.parmCSDSalesId(conPeek(csdSalesOrderList, 1));
    }

    endTask.parmBatchIdentifier(endTask.finalTaskIdentifier());

    if (_isBatchMode)
    {
        ListEnumerator soEnumerator;

        endTask.batchInfo().resetBatchHeader();
        endTask.batchInfo().parmGroupId(_currentBatchTask.GroupId);
        endTask.batchInfo().parmConstraintType(BatchConstraintType::And);
        endTask.batchInfo().parmDataareaId(_currentBatchTask.Company);
        _fulfillmentBatchHeader.addRuntimeTask(endTask, _anchorRecId);

        soEnumerator = _fulfillmentTaskList.getEnumerator();
        while (soEnumerator.moveNext())
        {
            _fulfillmentBatchHeader.addDependency(endTask, soEnumerator.current());
        }
    }
    else
    {
        endTask.run();
    }

    return endTask;
}

/// <summary>
/// CB395 CSD inter-branch transfer task - depends on every per-SO task AND the End/export
/// task, matching METSalesPickingListGenerationService.addCreateCSDTransferOrderTask.
/// </summary>
/// <param name = "_isBatchMode">True if running as a real batch job</param>
/// <param name = "_fulfillmentBatchHeader">Batch header to add the task to (batch mode only)</param>
/// <param name = "_anchorRecId">RecId to anchor the runtime task to (batch mode only)</param>
/// <param name = "_fulfillmentTaskList">Per-SO tasks the CSD task depends on</param>
/// <param name = "_endTask">End/export task the CSD task also depends on</param>
private void spawnCsdTransferOrderTask(boolean _isBatchMode, BatchHeader _fulfillmentBatchHeader, RefRecId _anchorRecId, List _fulfillmentTaskList, METSalesPickingListFulfillmentBatch _endTask)
{
    if (conLen(csdSalesOrderList) == 0)
    {
        return;
    }

    SysOperationServiceController      csdController = METCreateCSDTransferOrderController::construct(csdSalesOrderList);
    METCreateCSDTransferOrderContract  csdContract    = csdController.getDataContractObject() as METCreateCSDTransferOrderContract;
    csdContract.parmContinueFromStagingLane(continueFromStagingLane);

    if (_isBatchMode)
    {
        ListEnumerator csdSoEnumerator;

        _fulfillmentBatchHeader.addRuntimeTask(csdController, _anchorRecId);

        csdSoEnumerator = _fulfillmentTaskList.getEnumerator();
        while (csdSoEnumerator.moveNext())
        {
            _fulfillmentBatchHeader.addDependency(csdController, csdSoEnumerator.current(), BatchDependencyStatus::Finished);
        }
        _fulfillmentBatchHeader.addDependency(csdController, _endTask, BatchDependencyStatus::Finished);
    }
    else
    {
        csdController.parmShowDialog(false);
        csdController.startOperation();
    }
}

/// <summary>
/// LPT bin-packing: collect lines by item, sort items by line count descending, then
/// greedily assign items to the smallest bundle.
/// </summary>
/// <param name = "_salesIdContainer">Eligible SalesIds to bundle</param>
/// <param name = "_taskCount">Number of bundles to produce</param>
/// <returns>Container of bundles, each a container of SalesLine RecIds</returns>
private container buildLineTaskBundles(container _salesIdContainer, int _taskCount)
{
    Map        itemLineMap   = new Map(Types::String, Types::Container);
    Map        bundleSizeMap = new Map(Types::Integer, Types::Integer);
    container  bundleLines;
    container  itemIdArr;
    int        i;

    for (i = 1; i <= _taskCount; i++)
    {
        bundleLines += [conNull()];
        bundleSizeMap.insert(i, 0);
    }

    itemIdArr = this.collectLinesByItem(_salesIdContainer, itemLineMap);
    itemIdArr = this.sortItemsByLineCountDescending(itemIdArr, itemLineMap);

    return this.assignItemsToBundles(itemIdArr, itemLineMap, bundleLines, bundleSizeMap, _taskCount);
}

/// <summary>
/// Greedily assigns each item's lines to whichever bundle currently has the fewest lines.
/// </summary>
/// <param name = "_itemIdArr">Items in the order to assign</param>
/// <param name = "_itemLineMap">Map(ItemId -> lines)</param>
/// <param name = "_bundleLines">Bundles to fill</param>
/// <param name = "_bundleSizeMap">Running line count per bundle</param>
/// <param name = "_taskCount">Number of bundles</param>
/// <returns>The filled bundles</returns>
private container assignItemsToBundles(container _itemIdArr, Map _itemLineMap, container _bundleLines, Map _bundleSizeMap, int _taskCount)
{
    int i, bundleIdx;

    for (i = 1; i <= conLen(_itemIdArr); i++)
    {
        str        itemId         = conPeek(_itemIdArr, i);
        container  linesForItem   = _itemLineMap.lookup(itemId);
        int        smallestBundle = 1;
        int        smallestSize   = _bundleSizeMap.lookup(1);

        for (bundleIdx = 2; bundleIdx <= _taskCount; bundleIdx++)
        {
            int bundleSize = _bundleSizeMap.lookup(bundleIdx);

            if (bundleSize < smallestSize)
            {
                smallestSize   = bundleSize;
                smallestBundle = bundleIdx;
            }
        }

        _bundleLines = conPoke(_bundleLines, smallestBundle, conPeek(_bundleLines, smallestBundle) + linesForItem);
        _bundleSizeMap.insert(smallestBundle, smallestSize + conLen(linesForItem));
    }

    return _bundleLines;
}
